using System.Diagnostics;
using Purview.Telemetry;

namespace Purview.EventSourcing.CosmosDb.Snapshots;

/// <summary>
/// Telemetry used to record metrics for the Azure Cosmos DB snapshot event store.
/// </summary>
/// <remarks>
/// Implementations are generated by the Purview telemetry source generator from the
/// <see cref="Meter"/> attribute on this interface.
/// </remarks>
[ActivitySource]
[Logger]
[Meter]
public interface ICosmosDbSnapshotEventStoreTelemetry
{
	// Activities (distributed tracing)
	//
	// Snapshot and query spans only. Cosmos DB persists no event stream - it delegates aggregate
	// reads and writes to an inner event store, which emits the aggregate-level spans. Adding them
	// here too would double-count every operation in a trace.

	/// <summary>
	/// Starts an activity representing writing an aggregate snapshot.
	/// </summary>
	/// <param name="aggregateId">The id of the aggregate being snapshotted.</param>
	/// <param name="aggregateTypeFullName">The full name of the aggregate type.</param>
	/// <returns>The activity, or <see langword="null"/> when tracing is not enabled.</returns>
	[Activity]
	Activity? SnapshotAggregate(string aggregateId, [Baggage] string aggregateTypeFullName);

	/// <summary>
	/// Starts an activity representing a snapshot query.
	/// </summary>
	/// <param name="operation">The query shape, for example <c>Query</c>, <c>List</c> or <c>Count</c>.</param>
	/// <param name="aggregateTypeFullName">The full name of the aggregate type.</param>
	/// <returns>The activity, or <see langword="null"/> when tracing is not enabled.</returns>
	[Activity]
	Activity? QuerySnapshots(string operation, [Baggage] string aggregateTypeFullName);

	/// <summary>
	/// Records that a snapshot was created for the given aggregate type.
	/// </summary>
	/// <param name="aggregateType">The name of the aggregate type the snapshot was created for.</param>
	[Counter(AutoIncrement = true)]
	void SnapshotCreated(string aggregateType);
}
